@SpringBootTest(properties={"ticket.delivery.enabled=false","ticket.admission.enabled=false","ticket.orders.enabled=true","ticket.purchases.enabled=true","ticket.mock-payments.enabled=true","ticket.expiry.enabled=false","ticket.stock-recovery.enabled=false","ticket.pre-debit.enabled=false"})
@org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc
@TestInstance(TestInstance.Lifecycle.PER_CLASS)
class StockCheckoutIntegrationTest {
 @Autowired StockRecoveryStore recovery;@Autowired StockRecoveryWorker worker;@Autowired StockHoldService holds;@Autowired StockSettlementService settlement;@Autowired StockProjectionService projections;@Autowired PurchaseService purchases;@Autowired OrderService orders;@Autowired CustomerService customers;@Autowired CatalogService catalog;
 @Autowired JdbcTemplate db;@Autowired StringRedisTemplate redis;@Autowired ObjectMapper json;@Autowired AdmissionSettings settings;@Autowired AdmissionService admission;@Autowired PlatformTransactionManager transactions;
 @Autowired StockCheckoutService off;@Autowired org.springframework.test.web.servlet.MockMvc mvc;StockCheckoutService checkout;
 RedisTicketLedger ledger;Set<String> keys=new HashSet<>();String manager="recovery-"+UUID.randomUUID();
 record Fixture(Principal owner,UUID ticket,Place body,Intent intent) {}
 @BeforeAll void seed(){assertEquals("ticket_demo",db.queryForObject("SELECT current_database()",String.class));checkout=new StockCheckoutService(db,orders,purchases,holds,admission,new PreDebitSettings(true),json,transactions);ledger=RedisTicketLedger.epochs(redis,json,settings.namespace());db.update("INSERT INTO staff_account VALUES(?,?,?,?,true)",UUID.randomUUID(),manager,"unused synthetic hash","MANAGER");}
 @AfterEach void cleanup(){redis.delete(keys);keys.clear();}
 Principal customer(){var c=customers.register("sp-"+UUID.randomUUID().toString().substring(0,30),"合成",UUID.randomUUID().toString());return customers.authenticate(c.token()).orElseThrow();}
 Fixture fixture(){return fixture(7200);}
 Fixture fixture(int seconds){var e=catalog.createEvent(manager,new EventInput(UUID.randomUUID(),0L,"bridge-"+UUID.randomUUID(),"合成演出","不售票","隔離"));var now=OffsetDateTime.now();var s=catalog.createSession(manager,e.id(),new SessionInput(UUID.randomUUID(),0L,"合成",now.plusDays(2),now.minusHours(1),now.plusSeconds(seconds)));var t=catalog.createTicket(manager,s.id(),new TicketInput(UUID.randomUUID(),0L,"一般",1200,4,4));catalog.transition(manager,e.id(),new Transition(UUID.randomUUID(),1L),true);ready(t.id());var p=customer();var b=new Place(UUID.randomUUID(),t.id(),1,1,1200);return new Fixture(p,t.id(),b,null);}
 void ready(UUID t){var c=projections.begin(t,UUID.randomUUID(),projections.inspect(t).sourceRevision());keys.add(ledger.key(t,c.generation()));assertEquals("READY",projections.complete(c.requestId()).state());}
 Purchase accept(Fixture f){return checkout.submit(f.owner(),f.body()).purchase();}
 UUID event(Purchase p){return db.queryForObject("SELECT id FROM purchase_outbox WHERE purchase_id=?",UUID.class,p.id());}
 Purchase reserve(Fixture f){var p=accept(f);assertTrue(purchases.process(event(p)));return purchases.detail(f.owner(),p.id());}
 Claim claim(Fixture f){var i=holds.inspect(intent(f)).intent();return new Claim(i.generation(),i.id(),i.owner(),i.quantity(),i.deadlineAt().toInstant().toEpochMilli(),db.queryForObject("SELECT claim_fingerprint FROM stock_hold_intent WHERE id=?",String.class,i.id()));}
 String decision(Fixture f){return db.queryForObject("SELECT target FROM stock_hold_decision WHERE intent_id=?",String.class,intent(f));}
 int held(Fixture f){return db.queryForObject("SELECT held FROM ticket_type WHERE id=?",Integer.class,f.ticket());}
 void problem(String code,Runnable op){assertEquals(code,assertThrows(Problem.class,op::run).code);}
 void active(Fixture f){problem("ACTIVE_STOCK_INTENTS",()->projections.begin(f.ticket(),UUID.randomUUID(),projections.inspect(f.ticket()).sourceRevision()));}



 UUID intent(Fixture f){return db.queryForObject("SELECT id FROM stock_hold_intent WHERE customer_id=? AND request_id=?",UUID.class,f.owner().id(),f.body().requestId());}
 int count(String table,Fixture f){return db.queryForObject("SELECT count(*) FROM "+table+" WHERE customer_id=?",Integer.class,f.owner().id());}
 @Test void wholeEntryCommitsIntentLuaAndExactAcceptanceBeforeFormalHold(){var f=fixture();var p=checkout.submit(f.owner(),f.body());assertEquals("PROCESSING",p.state());assertNotNull(p.purchase());assertFalse(p.canRetrySameRequest());assertEquals(p.deadlineAt(),holds.inspect(intent(f)).intent().deadlineAt());assertEquals(1,count("stock_hold_intent",f));assertEquals(1,count("purchase_request",f));assertEquals(1,count("purchase_command",f));assertEquals(0,held(f));assertEquals(Status.HELD,ledger.lookup(f.ticket(),claim(f)).receipt().status());assertEquals(1,db.queryForObject("SELECT count(*) FROM stock_recovery_job WHERE intent_id=?",Integer.class,intent(f)));}
 @Test void originalGetIsOwnerVerifiedPgOnlyAndDoesNotResolveRedis(){var f=fixture();var p=checkout.submit(f.owner(),f.body());redis.delete(ledger.key(f.ticket(),1));assertEquals(p,checkout.progress(f.owner(),f.body().requestId()));assertEquals(p,off.submit(f.owner(),f.body()));assertEquals(0,held(f));assertEquals("READY",projections.inspect(f.ticket()).state());assertEquals(0,db.queryForObject("SELECT count(*) FROM stock_hold_ack WHERE intent_id=?",Integer.class,intent(f)));}
 @Test void flagOffFreshRequestCreatesNothingAndPublicDefaultIsFalse(){var f=fixture();problem("PREDEBIT_DISABLED",()->off.submit(f.owner(),f.body()));assertEquals(0,count("stock_hold_intent",f));assertEquals(0,count("purchase_request",f));var e=db.queryForObject("SELECT s.event_id FROM ticket_type t JOIN event_session s ON s.id=t.session_id WHERE t.id=?",UUID.class,f.ticket());assertFalse(catalog.detail(e,true).preDebitEnabled());}
 @Test void requestedFlagNeedsAllConfiguredRecoveryAndDeliveryDependencies(){assertFalse(new PreDebitSettings(true,true,true,false,true,true,true).enabled());assertFalse(new PreDebitSettings(true,true,true,true,false,true,true).enabled());assertFalse(new PreDebitSettings(true,true,true,true,true,false,true).enabled());assertFalse(new PreDebitSettings(true,true,true,true,true,true,false).enabled());assertTrue(new PreDebitSettings(true,true,true,true,true,true,true).enabled());}
 @Test void preparedPgIntentIsReadableBeforeLuaAndSameBodyResumes(){var f=fixture();var i=holds.prepare(f.owner(),f.body());assertEquals("PREPARED",checkout.progress(f.owner(),f.body().requestId()).state());assertEquals(0,ledger.snapshot(f.ticket(),1).snapshot().held());assertEquals("PROCESSING",checkout.submit(f.owner(),f.body()).state());assertEquals(i.id(),intent(f));assertEquals(1,ledger.snapshot(f.ticket(),1).snapshot().entries());}
 @Test void luaSuccessBeforePgHeldRollbackUsesOriginalReceiptOnRetry(){var f=fixture();var i=holds.prepare(f.owner(),f.body());db.execute("ALTER TABLE stock_hold_progress ADD CONSTRAINT checkout_held_fault CHECK(intent_id<>'"+i.id()+"'::uuid OR state<>'HELD') NOT VALID");try{assertThrows(org.springframework.dao.DataIntegrityViolationException.class,()->checkout.submit(f.owner(),f.body()));assertEquals("PREPARED",checkout.progress(f.owner(),f.body().requestId()).state());assertEquals(Status.HELD,ledger.lookup(f.ticket(),claim(f)).receipt().status());assertEquals(0,count("purchase_request",f));}finally{db.execute("ALTER TABLE stock_hold_progress DROP CONSTRAINT checkout_held_fault");}assertEquals("PROCESSING",checkout.submit(f.owner(),f.body()).state());assertEquals(1,ledger.snapshot(f.ticket(),1).snapshot().held());}
 @Test void acceptanceRollbackKeepsHeldAndProgressNeverInventsFormalReceipt(){var f=fixture();var i=holds.prepare(f.owner(),f.body());db.execute("ALTER TABLE stock_hold_acceptance ADD CONSTRAINT checkout_link_fault CHECK(intent_id<>'"+i.id()+"'::uuid) NOT VALID");try{assertThrows(org.springframework.dao.DataIntegrityViolationException.class,()->checkout.submit(f.owner(),f.body()));var p=checkout.progress(f.owner(),f.body().requestId());assertEquals("HELD",p.state());assertNull(p.purchase());assertTrue(p.canRetrySameRequest());assertEquals(0,count("purchase_request",f));assertEquals(0,held(f));}finally{db.execute("ALTER TABLE stock_hold_acceptance DROP CONSTRAINT checkout_link_fault");}assertEquals("PROCESSING",checkout.submit(f.owner(),f.body()).state());}
 @Test void sixConcurrentFullCoordinatorsCreateOneReceiptLinkAndOutbox()throws Exception{var f=fixture();try(var pool=Executors.newFixedThreadPool(6)){var tasks=new ArrayList<Callable<StockCheckoutService.Progress>>();for(int i=0;i<6;i++)tasks.add(()->checkout.submit(f.owner(),f.body()));var r=pool.invokeAll(tasks);var p=r.getFirst().get();for(var v:r)assertEquals(p,v.get());}assertEquals(1,count("stock_hold_intent",f));assertEquals(1,count("purchase_request",f));assertEquals(1,ledger.snapshot(f.ticket(),1).snapshot().entries());assertEquals(0,held(f));}
 @Test void outsiderCannotReadAndUuidsAreIndependentlyScoped(){var f=fixture();checkout.submit(f.owner(),f.body());var b=customer();problem("NOT_FOUND",()->checkout.progress(b,f.body().requestId()));var own=checkout.submit(b,f.body());assertNotEquals(own.purchase().id(),checkout.progress(f.owner(),f.body().requestId()).purchase().id());assertEquals(2,ledger.snapshot(f.ticket(),1).snapshot().held());}
 @Test void changedBodyCannotReplayEvenWhenFlagOff(){var f=fixture();checkout.submit(f.owner(),f.body());problem("REQUEST_CONFLICT",()->off.submit(f.owner(),new Place(f.body().requestId(),f.ticket(),2,1,2400)));problem("REQUEST_CONFLICT",()->off.submit(f.owner(),new Place(f.body().requestId(),UUID.randomUUID(),1,1,1200)));}
 @Test void legacySubmitOriginalReplaySurvivesFlagOffButCommandCollisionDoesNot(){var f=fixture();var legacy=purchases.submit(f.owner(),f.body());assertEquals(legacy,off.submit(f.owner(),f.body()).purchase());assertEquals(0,count("stock_hold_intent",f));var c=new Cancel(UUID.randomUUID(),1);purchases.cancel(f.owner(),legacy.id(),c);problem("REQUEST_CONFLICT",()->checkout.submit(f.owner(),new Place(c.requestId(),f.ticket(),1,1,1200)));var other=fixture();orders.place(other.owner(),other.body());problem("REQUEST_CONFLICT",()->checkout.submit(other.owner(),other.body()));}
 @Test void newLoginCanReadButCannotAdoptOldUnacceptedSession(){var f=fixture();String password=UUID.randomUUID().toString(),handle="new-session-"+UUID.randomUUID().toString().substring(0,24);var first=customers.register(handle,"合成",password);var original=customers.authenticate(first.token()).orElseThrow();holds.prepare(original,f.body());var id=db.queryForObject("SELECT id FROM stock_hold_intent WHERE customer_id=?",UUID.class,original.id());holds.apply(id);customers.logout(first.token());var issued=customers.login(handle,password);var who=customers.authenticate(issued.token()).orElseThrow();var p=checkout.progress(who,f.body().requestId());assertEquals("HELD",p.state());assertFalse(p.canRetrySameRequest());assertEquals(p,checkout.submit(who,f.body()));assertEquals(0,db.queryForObject("SELECT count(*) FROM stock_hold_acceptance WHERE intent_id=?",Integer.class,id));}
 @Test void revokedPrincipalCannotReadOrResumeAndExpiryNeverExtends()throws Exception{var f=fixture(2);holds.prepare(f.owner(),f.body());holds.apply(intent(f));var before=holds.inspect(intent(f)).intent().deadlineAt();while(OffsetDateTime.now().isBefore(before))Thread.sleep(20);var p=checkout.submit(f.owner(),f.body());assertEquals("HELD",p.state());assertFalse(p.canRetrySameRequest());assertEquals(before,p.deadlineAt());holds.recoverUnused(intent(f),()->{});assertEquals("ABORTED",checkout.progress(f.owner(),f.body().requestId()).state());assertEquals("ABORTED",off.submit(f.owner(),f.body()).state());assertEquals(0,count("purchase_request",f));}
 @Test void corruptOrMissingProjectionLeavesDurablePendingAndNeverFailsOpen(){var f=fixture();holds.prepare(f.owner(),f.body());redis.delete(ledger.key(f.ticket(),1));var p=checkout.submit(f.owner(),f.body());assertEquals("PREPARED",p.state());assertNull(p.purchase());assertEquals(0,count("purchase_request",f));assertEquals("DIRTY",projections.inspect(f.ticket()).state());assertFalse(redis.hasKey(ledger.key(f.ticket(),1)));}
 @Test void acceptedCancelAndWorkerUseFormalPgResultRegardlessOfRedis(){var f=fixture();var p=checkout.submit(f.owner(),f.body()).purchase();redis.delete(ledger.key(f.ticket(),1));purchases.process(event(p));var current=off.progress(f.owner(),f.body().requestId());assertEquals("RESERVED",current.state());assertEquals(1,held(f));assertEquals(current,off.submit(f.owner(),f.body()));assertEquals("KEY_MISSING",settlement.reconcile(intent(f)).resolution());var g=fixture();var q=checkout.submit(g.owner(),g.body()).purchase();purchases.cancel(g.owner(),q.id(),new Cancel(UUID.randomUUID(),1));assertEquals("CANCELLED",off.progress(g.owner(),g.body().requestId()).state());}
 @Test void missingOriginalIs404AndReadDoesNotPrepare(){var f=fixture();problem("NOT_FOUND",()->off.progress(f.owner(),f.body().requestId()));assertEquals(0,count("stock_hold_intent",f));}
 @Test void originalCurrentSessionMustBeValidAtReadAndResume(){var f=fixture();holds.prepare(f.owner(),f.body());db.update("UPDATE customer_account SET enabled=false WHERE id=?",f.owner().id());problem("UNAUTHENTICATED",()->checkout.progress(f.owner(),f.body().requestId()));problem("UNAUTHENTICATED",()->checkout.submit(f.owner(),f.body()));assertEquals(0,count("purchase_request",f));}
 @Test void earlyAdmissionDenialCreatesNoPreDebit(){var f=fixture();var enabled=new AdmissionService(db,redis,json,new AdmissionSettings(true,settings.namespace(),2,100,30,20,300,30,5));var c=new StockCheckoutService(db,orders,purchases,holds,enabled,new PreDebitSettings(true),json,transactions);problem("ADMISSION_REQUIRED",()->c.submit(f.owner(),f.body()));assertEquals(0,count("stock_hold_intent",f));}
 @Test void outerTransactionCannotWrapIndependentPhases(){var f=fixture();new TransactionTemplate(transactions).execute(tx->{assertThrows(IllegalStateException.class,()->checkout.submit(f.owner(),f.body()));assertThrows(IllegalStateException.class,()->checkout.progress(f.owner(),f.body().requestId()));return null;});assertEquals(0,count("stock_hold_intent",f));}
 @Test void stockRecoveryReviewIsExposedWithoutRawWorkerIdentity(){var f=fixture();holds.prepare(f.owner(),f.body());holds.apply(intent(f));redis.delete(ledger.key(f.ticket(),1));redis.opsForValue().set(ledger.key(f.ticket(),1),"synthetic-corrupt");assertEquals("ABORTING",holds.abandon(intent(f)).state());var c=recovery.claim(30);for(int n=0;c.isPresent()&&!c.get().intentId().equals(intent(f))&&n<1000;n++){worker.run(c.get());c=recovery.claim(30);}assertTrue(c.isPresent());assertTrue(recovery.failed(c.get(),"REDIS_CORRUPT",true));var p=checkout.progress(f.owner(),f.body().requestId());assertEquals("REVIEW",p.state());assertFalse(p.canRetrySameRequest());assertNull(p.purchase());}
 @Test void httpOwnerCsrfSpoofAndReadProgressSafety()throws Exception{var f=fixture();var issued=customers.register("entry-http-"+UUID.randomUUID().toString().substring(0,24),"合成",UUID.randomUUID().toString());var who=customers.authenticate(issued.token()).orElseThrow();var cookie=new jakarta.servlet.http.Cookie("TICKET_CUSTOMER_SESSION",issued.token());var body=json.writeValueAsString(f.body());var target="/api/customer/purchase-attempts";mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get(target+"/"+f.body().requestId())).andExpect(org.springframework.test.web.servlet.result.MockMvcResultMatchers.status().isUnauthorized());mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post(target).cookie(cookie).contentType("application/json").content(body)).andExpect(org.springframework.test.web.servlet.result.MockMvcResultMatchers.status().isForbidden());var csrf=mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get("/api/customer/auth/csrf")).andReturn();var n=json.readTree(csrf.getResponse().getContentAsString());var cc=csrf.getResponse().getCookie("TICKET_CUSTOMER_CSRF");mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post(target).cookie(cookie,cc).header(n.get("headerName").asText(),n.get("token").asText()).contentType("application/json").content(body.substring(0,body.length()-1)+",\"customerId\":\"spoof\"}")).andExpect(org.springframework.test.web.servlet.result.MockMvcResultMatchers.status().isBadRequest());mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post(target).cookie(cookie,cc).header(n.get("headerName").asText(),n.get("token").asText()).contentType("application/json").content(body)).andExpect(org.springframework.test.web.servlet.result.MockMvcResultMatchers.status().isConflict());holds.prepare(who,f.body());mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get(target+"/"+f.body().requestId()).cookie(cookie).header("X-Expected-Customer-ID",who.id())).andExpect(org.springframework.test.web.servlet.result.MockMvcResultMatchers.status().isOk()).andExpect(org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath("$.state").value("PREPARED")).andExpect(org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath("$.sessionHash").doesNotExist()).andExpect(org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath("$.customerId").doesNotExist()).andExpect(org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath("$.intentId").doesNotExist()).andExpect(org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath("$.canRetrySameRequest").value(false));mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get(target+"/"+f.body().requestId()).cookie(cookie).header("X-Expected-Customer-ID",UUID.randomUUID())).andExpect(org.springframework.test.web.servlet.result.MockMvcResultMatchers.status().isUnauthorized());}
}
